import { jsx as _jsx } from "react/jsx-runtime";
import { forwardRef, useEffect, useState } from 'react';
import { BaseIcon } from './BaseIcon';
import { toPascalCase, NETWORK_ICON_IMPORT_MAP, TOKEN_ICON_IMPORT_MAP, WALLET_ICON_IMPORT_MAP, EXCHANGE_ICON_IMPORT_MAP, } from './utils';
/**
 * DynamicIcon component dynamically loads and renders icons based on the provided metadata and type.
 *
 * @param {IDynamicIcon} props
 * @param {React.ForwardedRef<SVGSVGElement>} ref
 * @returns {ReactElement | null} JSX Element for the DynamicIcon component or null if the icon fails to load.
 */
export const DynamicIcon = forwardRef(({ size, color, className, variant, fallback, metadata, type }, ref) => {
    const [IconComponent, setIconComponent] = useState(null);
    useEffect(() => {
        const loadIcon = async () => {
            let importFunction;
            if (!metadata) {
                if (!fallback)
                    return null;
                setIconComponent(_jsx(BaseIcon, { ref: ref, size: size, color: color, className: className, fallback: fallback }));
                return;
            }
            switch (type) {
                case 'token':
                    importFunction =
                        TOKEN_ICON_IMPORT_MAP[`Token${metadata.symbol.toUpperCase()}`];
                    break;
                case 'network':
                    importFunction =
                        NETWORK_ICON_IMPORT_MAP[`Network${toPascalCase(metadata.name)}`] ??
                            NETWORK_ICON_IMPORT_MAP[`Network${toPascalCase(metadata.id)}`];
                    break;
                case 'wallet':
                    importFunction =
                        WALLET_ICON_IMPORT_MAP[`Wallet${toPascalCase(metadata.name)}`] ??
                            WALLET_ICON_IMPORT_MAP[`Wallet${toPascalCase(metadata.id)}`];
                    break;
                case 'exchange':
                    importFunction =
                        // prettier-ignore
                        EXCHANGE_ICON_IMPORT_MAP[`Exchange${toPascalCase(metadata.name)}`] ??
                            EXCHANGE_ICON_IMPORT_MAP[`Exchange${toPascalCase(metadata.id)}`];
                    break;
                default:
                    throw new Error(`invalid type ${type}`);
            }
            if (importFunction) {
                try {
                    const { default: ImportedIcon } = await importFunction();
                    setIconComponent(_jsx(ImportedIcon, { ref: ref, size: size, color: color, className: className, variant: variant }));
                }
                catch (error) {
                    if (fallback) {
                        setIconComponent(_jsx(BaseIcon, { ref: ref, size: size, color: color, className: className, fallback: fallback }));
                    }
                }
            }
            else {
                if (fallback) {
                    setIconComponent(_jsx(BaseIcon, { ref: ref, size: size, color: color, className: className, fallback: fallback }));
                }
            }
        };
        loadIcon();
    }, [ref, size, color, className, variant, fallback]);
    return IconComponent;
});
